"""Task-local validation for webhook_endpoint.py.

Checks that the module is syntactically valid and contains the required
behaviour markers for the requested Stripe webhook implementation.
"""

import ast
import py_compile
import sys

SOURCE_PATH = "webhook_endpoint.py"

REQUIRED_MARKERS = [
    "payment_intent.succeeded",
    "payment_intent.payment_failed",
    "stripe.Webhook.construct_event",   # signature verification
    "Stripe-Signature",                  # signature header read
    "SignatureVerificationError",
    "_EVENT_HANDLERS",                   # dispatch table
    "400",                               # reject invalid payloads/signatures
    "500",                               # handler failure -> Stripe retries
    "STRIPE_WEBHOOK_SECRET",             # secret via environment, never literal
]


def main() -> None:
    failures: list[str] = []

    # 1) Syntax check (parses without importing third-party modules).
    try:
        py_compile.compile(SOURCE_PATH, doraise=True)
        print(f"OK  py_compile: {SOURCE_PATH} is syntactically valid")
    except py_compile.PyCompileError as exc:  # pragma: no cover
        failures.append(f"py_compile failed: {exc}")

    source = open(SOURCE_PATH, encoding="utf-8").read()
    tree = ast.parse(source)

    # 2) Required functional markers are present.
    for marker in REQUIRED_MARKERS:
        if marker not in source:
            failures.append(f"missing required marker: {marker!r}")
        else:
            print(f"OK  marker present: {marker}")

    # 3) The two requested event types map to handler functions.
    handlers: dict[str, str] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if (
                    isinstance(target, ast.Name)
                    and target.id == "_EVENT_HANDLERS"
                    and isinstance(node.value, ast.Dict)
                ):
                    for key, value in zip(node.value.keys, node.value.values):
                        if isinstance(key, ast.Constant) and isinstance(
                            value, ast.Name
                        ):
                            handlers[key.value] = value.id

    for event_type in ("payment_intent.succeeded", "payment_intent.payment_failed"):
        handler = handlers.get(event_type)
        if handler is None:
            failures.append(f"no dispatch entry for {event_type}")
        else:
            # Confirm the referenced handler function is actually defined.
            defined = any(
                isinstance(node, ast.FunctionDef) and node.name == handler
                for node in ast.walk(tree)
            )
            if not defined:
                failures.append(
                    f"dispatch entry {event_type} -> {handler} but no such function"
                )
            else:
                print(f"OK  dispatch: {event_type} -> {handler}()")

    # 4) Webhook route exists with POST method.
    route_ok = any(
        isinstance(node, ast.FunctionDef)
        and any(
            isinstance(d, ast.Call)
            and isinstance(d.func, ast.Attribute)
            and d.func.attr == "route"
            and any(
                isinstance(a, ast.Constant) and a.value == "/webhook"
                for a in d.args
            )
            and any(
                isinstance(kw.value, ast.Constant) and kw.value.value == "POST"
                for kw in d.keywords
            )
            for d in node.decorator_list
        )
        for node in ast.walk(tree)
    )
    if route_ok:
        print("OK  POST route registered at /webhook")
    else:
        failures.append("no POST route registered at /webhook")

    # 5) Handler failures must yield 500 (so Stripe retries delivery).
    if "return jsonify({\"error\": \"Handler failed\"}), 500" not in source:
        failures.append("handler failure path does not return 500")

    if failures:
        print("\nVALIDATION FAILED:")
        for item in failures:
            print(f"  - {item}")
        sys.exit(1)

    print("\nAll validation checks passed.")


if __name__ == "__main__":
    main()

